tape( 'the function performs the matrix-matrix operation `C = α*A*B**T + C = α*B*A**T + β*C` (row-major, lower, no-transpose)', function test( t ) {
	var expected;
	var data;
	var out;
	var a;
	var b;
	var c;

	data = rlnt;

	a = new Float32Array( data.A );
	b = new Float32Array( data.B );
	c = new Float32Array( data.C );

	expected = new Float32Array( data.C_out );

	out = ssyr2k( data.order, data.uplo, data.trans, data.N, data.K, data.alpha, a, data.lda, b, data.ldb, data.beta, c, data.ldc );
	t.strictEqual( out, c, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

